import{_ as a,a0 as r,w as l,s as d,ao as o,I as s,x as n,a1 as i,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const F=JSON.parse('{"title":"Linux下NTFS分区的修复和恢复 | LCTT x X-CMD","titleTemplate":false,"description":"Linux下NTFS分区的修复和恢复 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux下NTFS分区的修复和恢复 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux下NTFS分区的修复和恢复 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/NTFS Partition Repair and Recovery In Linux","title":"Linux下NTFS分区的修复和恢复","tag":"201310","desc":""},"relativePath":"201310/NTFS Partition Repair and Recovery In Linux.md","filePath":"[post].md"}'),u={name:"201310/NTFS Partition Repair and Recovery In Linux.md"};function T(x,t,f,m,S,L){const e=r("Link");return l(),d("div",null,[t[14]||(t[14]=o(`<h1 id="linux下ntfs分区的修复和恢复" tabindex="-1">Linux下NTFS分区的修复和恢复 <a class="header-anchor" href="#linux下ntfs分区的修复和恢复" aria-label="Permalink to “Linux下NTFS分区的修复和恢复”">​</a></h1><p>我们时不时需要帮助我们的朋友、家人、熟人、商业伙伴或者其他杂七杂八的人摆脱使用Windows的时候遇到的困境。尽管我们不像他们一样日常遇到各种问题，却经常是在他们有难的时候会求助的人。此外,甚至我们自己的Windows分区/驱动器也会出现问题（毕竟，有时候我们还是需要玩儿会儿游戏，而且，尽管Steam在努力，但Linux还不是游戏玩家的梦想之地），但愿不会如此。下面让我们看一两个我们可能会遇到的状况，那时我们可以用手边的Linux环境和一些NTFS分区恢复工具来修复它们。</p><p>###简单修复</p><p>Windows 系统通常能很好的处理异常的“冷重启”（断电，关闭插线板的电源，或家里的小人儿手指随意按导致关机)。事实上，至今为止，最有效的修复Windows桌面问题的方法就是简单的重启系统。但是，Windows分区偶尔会显示系统需要进行驱动器一致性检测。不这么做的话，在几次重启后可能会引起文件系统状况恶化而使系统变得更糟。众所周知，Windows文件系统检查超级慢，而且经常不得不做好几次才能清理掉文件系统的“脏（dirty）”标志。</p><p>下面介绍一个叫“ntfsfix”的小工具，在基于Debian的系统（如 Ubuntu）可以通过下面的命令下载：</p><pre><code>sudo apt-get install ntfsfix
</code></pre><p>或者在基于RPM的系统（如 Red Hat 或 CentOS）中通过下面的命令下载:</p><pre><code>sudo yum install ntfsfix
</code></pre><p>这个‘ntfsfix’工具能快速的修复常见的错误以及NTFS分区不一致的问题。最常用的命令不用带任何参数。 它也可以报出来那些没有修复掉的项，然后我们能通过以下选项来修复它们：</p><ul><li>-b: 清除磁盘上的坏的扇区 (可以在从一个旧磁盘往新的磁盘上克隆之后使用)</li><li>-d: 清除“脏”标志。“脏”标志是Linux不能挂载一个Windows分区的最常见的原因，通常发生在Windows断电前没有正常关机的情况。</li><li>-n: 除了在标准输出上显示它要完成的(换句话说，就是需要修复哪些)之外不做任何事。</li></ul><p>过去Windows在启动前，用NTFS Disk Check来重置“脏”标志，常常要花几个小时。而‘ntfsfix’完成这个仅仅只需要大约三秒的时。</p><p>###深度修复</p><p>不幸的是, 并非所有的问题都能被快速修复。事实上，有非常多的昂贵的磁盘恢复软件（通常属于“磁盘取证”类的软件，因为是在筛选损坏磁盘的时候调查人员使用的）用来修复那些加电但不能启动或者不能访问文件系统的磁盘。</p>`,13)),s("p",null,[t[1]||(t[1]=n("有一个神奇的工具，免费而强大（而且如果在你本地电脑使用的话，可以放到一个可引导的救援Live CD里面）可以用来恢复你的Windows NTFS分区（而且，也能恢复EXT2/3/4，FAT/FAT32、exFAT、HFS和SunFS文件系统）。这个工具叫做",-1)),i(e,{href:"http://www.cgsecurity.org/wiki/TestDisk"},{default:p(()=>[...t[0]||(t[0]=[n("TestDisk",-1)])]),_:1}),t[2]||(t[2]=n("，在Debian和CentOS 的软件仓库中可用。Red Hat的软件仓库中并没有这个软件，但是安装它很容易。",-1))]),t[15]||(t[15]=o(`<pre><code>sudo apt-get install testdisk
</code></pre><p>在基于 RPM 的系统（如 Red Hat 或 CentOS）：</p><pre><code>sudo yum install testdisk
</code></pre><p>这个工具简直无与伦比。如果驱动器加电并且运转了，甚至当驱动器有物理损坏时，这个小工具仍会奇迹般的取出一些文件来。 你可以通过一个旧式风格的命令“sudo testdisk /dev/sdX”来启动它，这里‘X’是你的驱动器号，之后你会看到下面的界面：</p><p><img src="http://blog.linuxacademy.com/wp-content/uploads/2013/08/testdisk2.jpg" alt=""></p><p><em>TestDisk在终端中运行</em></p><p>这个工具使用起来很简单，只需要根据菜单提示进行操作，而且它是交互式的。它会扫描你指定的某个分区，然后把重建的目录和文件显示出来，然后你可以标记，并存到另外一磁盘或者分区里面。我已经成功地从Windows，OSX和linux分区里面恢复过文件，这些分区要么因为这种或那种原因不能启动，要么害怕启动之后可能彻底完蛋，总之，这些分区用不了多久就会彻底完蛋了。</p><p>说句实在的，你不能期望文件系统100%的恢复，尤其是你的驱动器已经有损坏了，不过至少聊胜于无吧，而且不用像去请专业人员处理那样花很多钱（实际上一分也不用花）。所以如果你的驱动器现在有问题了，那你可以用下这个工具。</p><p>###结束语</p><p>当你使用Linux的时候，磁盘修复要容易得多，当然也便宜的多，要么用USB转接器连接有问题的磁盘，要么从一个LiveCD启动，然后用CD里面的修复工具。本文中我们谈到的所有的工具都是免费使用，而且是在持续开发（更新）中。您可以在下面留言，谈一下你曾经不得不使用什么工具来从您磁盘的问题中恢复。</p><hr>`,11)),s("p",null,[t[4]||(t[4]=n("via: ",-1)),i(e,{href:"http://blog.linuxacademy.com/linux/ntfs-partition-repair-and-recovery-in-linux/"},{default:p(()=>[...t[3]||(t[3]=[n("http://blog.linuxacademy.com/linux/ntfs-partition-repair-and-recovery-in-linux/",-1)])]),_:1})]),s("p",null,[t[7]||(t[7]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[5]||(t[5]=[n("LCTT",-1)])]),_:1}),t[8]||(t[8]=n(" 原创翻译，",-1)),i(e,{href:"http://linux.cn/portal.php"},{default:p(()=>[...t[6]||(t[6]=[n("Linux中国",-1)])]),_:1}),t[9]||(t[9]=n(" 荣誉推出",-1))]),s("p",null,[t[12]||(t[12]=n("译者：",-1)),i(e,{href:"http://linux.cn/space/younel0925"},{default:p(()=>[...t[10]||(t[10]=[n("younel0925",-1)])]),_:1}),t[13]||(t[13]=n(" 校对：",-1)),i(e,{href:"http://linux.cn/space/jasminepeng"},{default:p(()=>[...t[11]||(t[11]=[n("jasminepeng",-1)])]),_:1})])])}const w=a(u,[["render",T]]);export{F as __pageData,w as default};
